expression:
grel:with(value.trim().toLowercase().replace(/[^a-z0-9]+/, "-").replace(/^-+|-+$/, ""), s,
  if(isBlank(value), null,
    if(if(isNull(cell.recon), false, cell.recon.matched),
      "http://www.wikidata.org/entity/" + cell.recon.match.id,
      "https://w3id.org/FAIR-course-UT/2025-2026/group2/data#org-" + if(isBlank(s), escape(value.trim(), "url"), s))))

